// Package locales embeds the ICU MessageFormat catalogs of the server (ADR-0009). A namespace is a directory locales/<BCP47>/<namespace>/ of files in the FormatJS JSON
// shape, one per area of its keys (ADR-0081); en is the source locale, en-XA and ar-XB are
// pseudo-locales generated by tools/i18n. Only internal/i18n reads this package.
package locales

import "embed"

// FS holds the <locale>/<namespace>/ directories of every namespace (ADR-0081). A directory pattern
// embeds the files of a new area without a change here; a new namespace needs its pattern, and TestFS
// fails until it has one.
//
//go:embed */server
var FS embed.FS
